import{z as m,x as i,o as l,c as s,q as r,j as t,D as E,d as B,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"内存管理与换入换出","description":"","frontmatter":{"title":"内存管理与换入换出","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-memory-management.md","filePath":"llm/edge-memory-management.md","lastUpdated":1791413859000}'),d={name:"llm/edge-memory-management.md"};function p(D,a,C,f,h,u){const A=i("Mermaid");return l(),s("div",null,[a[2]||(a[2]=r('<h1 id="内存管理与换入换出" tabindex="-1">内存管理与换入换出 <a class="header-anchor" href="#内存管理与换入换出" aria-label="Permalink to &quot;内存管理与换入换出&quot;">​</a></h1><div class="epigraph"><p>端侧的 OOM 不发生在加载失败那一下，发生在第三个会话的第 400 个 token：内存要按峰值记账，不按均值。</p><footer>—— 据 Apple Jetsam 与 Android lowmemorykiller、onTrimMemory 机制文档整理</footer></div><p><a href="/llm/edge-quantization-practice">上一课</a>把模型压到四五 GB 并在真机上验证，但「装得下」是瞬时判断：操作系统并不把标称内存全交给应用，会话在变长、KV 在涨、别的应用在抢。本课写内存作为长期受管资源：账怎么算、压力来了怎么让、多模型怎么换入换出。后课的能耗与路由都以这里的峰值账为输入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>账有四项：权重常驻、KV 随上下文线性涨、激活与工作缓冲、运行时自身。KV 一项最容易被漏算：GQA 八十亿参数级模型、fp16 存储，每 token 约十万字节量级，四千上下文就是半 GB——上下文上限不写进产品规格，上线后一定在长会话上撞墙。系统侧的真实可用量又远小于标称：iOS 的 jetsam 与 Android 的 lowmemorykiller 都按进程优先级与全局水位杀进程，应用能稳定持有的常常只有标称的一半，后台与扩展进程的限额更低。<span class="marginnote">「实际只有标称一半」是什么概念？8 GB 手机的单个应用常被限制在 4–5 GB 以内，后台进程更低；再扣掉系统水位，推理引擎真正能指望的往往只有 3–4 GB——4-bit 的 8B 模型（约 4 GB）加 KV 已经贴着天花板。可行性判断从「文件小于标称内存」改成「峰值账小于标称一半」，第一宗罪就犯了。</span>拿「文件大小小于标称内存」做可行性判断，是端侧最常见的第一宗罪。</p><h3 id="记账与让路" tabindex="-1">记账与让路 <a class="header-anchor" href="#记账与让路" aria-label="Permalink to &quot;记账与让路&quot;">​</a></h3><p><span class="marginnote">换算锚点：GQA 8B 级模型 fp16 KV 每 token 约 128 KB，4K 上下文约 0.5 GB。把上下文上限、KV 单价、峰值 RSS 三行写进发布规格，内存争议就结束了。</span></p><p>方法按层递进。mmap 加载是地基：权重只读、按需缺页、页可回收，<a href="/llm/gguf">GGUF</a> 容器就是为 mmap 与跨版本分发设计的，<a href="/llm/llamacpp">llama.cpp / ggml</a> 把这套实践在桌面与端上跑通。mmap 之后，「换入换出」的第一层由操作系统免费提供：内存紧张时页被回收，下次访问再从盘上读回。第二层才是应用策略：收到内存压力回调（onTrimMemory 的各级）就按序让路——先丢可重建的缓存与 KV，再卸载按需大模型，最后降档到常驻小模型。顺序要写死，不能在 OOM 边缘临场决定。<span class="marginnote">为什么顺序必须写死？临场决定意味着每次逼近 OOM 都在做不同的选择：这次丢掉用户正在看的会话 KV，下次卸掉刚预热好的 3 GB 大模型。固定顺序——先丢可重建的、再卸按需的、最后降档常驻的——保证任何一次压力下牺牲的都是最便宜的那块，把随机事故变成可预期行为。</span></p>',8)),(l(),t(n,null,{default:E(()=>[o(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%90%AF%E5%8A%A8%3A%20mmap%20%E6%9D%83%E9%87%8D%E4%B8%8E%E9%A2%84%E7%83%AD%22%5D%20--%3E%20R%5B%22%E8%BF%90%E8%A1%8C%3A%20KV%20%E9%9A%8F%E4%B8%8A%E4%B8%8B%E6%96%87%E6%B6%A8%22%5D%0A%20%20R%20--%3E%20W%7B%22%E5%86%85%E5%AD%98%E5%8E%8B%E5%8A%9B%E5%9B%9E%E8%B0%83%3F%22%7D%0A%20%20W%20--%3E%7C%E6%98%AF%7C%20D1%5B%22%E4%B8%A2%E7%BC%93%E5%AD%98%E4%B8%8E%20KV%22%5D%0A%20%20D1%20--%3E%20D2%7B%22%E4%BB%8D%E7%B4%A7%E5%BC%A0%3F%22%7D%0A%20%20D2%20--%3E%7C%E6%98%AF%7C%20D3%5B%22%E5%8D%B8%E8%BD%BD%E6%8C%89%E9%9C%80%E5%A4%A7%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20D2%20--%3E%7C%E5%90%A6%7C%20R%0A%20%20D3%20--%3E%20D4%5B%22%E9%99%8D%E6%A1%A3%E5%B8%B8%E9%A9%BB%E5%B0%8F%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"方法",tabindex:"-1"},[B("方法 "),e("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[4]||(a[4]=e("p",null,"多模型按「常驻/按需」分档：常驻小模型负责兜底与路由，按需大模型切换进来。切换成本是页面导入时间，冷启动的第一个 token 会明显变慢，所以预热要做成显式步骤——跑一个空 token 扫一遍热层，或对权重热页做锁定与预读；代价是别的工作集变小，两边都记进账。会话结束的清理同理：KV 立即释放；大模型保留与否看下次请求到达的概率，按 LRU 记账即可，不必发明新策略。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"为什么 mmap 是对的而「自己管一块大内存」通常是错的：权重访问模式是每 token 全量扫一遍，缺页由内核按全局水位统一调度，应用自己把内存锁死，系统就去杀别的进程或干脆杀你。KV 的增长是剩余的碎片源：按上下文上限一次分配到位，或按桶增长，别每 token 重新分配。预热与延迟加载的平衡点用实测定：预读省下的首 token 延迟，换来的是启动时更高的内存峰值，被系统盯上的风险也跟着涨。",-1)),a[7]||(a[7]=e("p",null,"两条加载路径在系统压力下的走向：",-1)),(l(),t(n,null,{default:E(()=>[o(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20LOAD%5B%22%E5%8A%A0%E8%BD%BD%204%20GB%20%E5%8F%AA%E8%AF%BB%E6%9D%83%E9%87%8D%22%5D%20--%3E%7C%22mmap%22%7C%20M1%5B%22%E6%8C%89%E9%9C%80%E7%BC%BA%E9%A1%B5%EF%BC%9A%E7%94%A8%E5%88%B0%E6%89%8D%E8%BD%BD%E5%85%A5%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E5%86%85%E5%AD%98%E7%B4%A7%E5%BC%A0%EF%BC%9A%E5%B9%B2%E5%87%80%E9%A1%B5%E8%A2%AB%E5%86%85%E6%A0%B8%E5%9B%9E%E6%94%B6%22%5D%0A%20%20M1%20--%3E%20M3%5B%22%E5%A4%9A%E8%BF%9B%E7%A8%8B%E5%8F%AF%E5%85%B1%E4%BA%AB%E5%90%8C%E4%B8%80%E4%BB%BD%E5%8F%AA%E8%AF%BB%E9%A1%B5%22%5D%0A%20%20LOAD%20--%3E%7C%22%E4%B8%80%E6%AC%A1%E6%80%A7%E8%AF%BB%E5%85%A5%E8%87%AA%E7%AE%A1%22%7C%20S1%5B%22%E5%90%AF%E5%8A%A8%E5%8D%B3%E5%8D%A0%E6%BB%A1%204%20GB%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E9%94%81%E6%AD%BB%E4%B8%8D%E8%BF%98%EF%BC%9A%E7%B3%BB%E7%BB%9F%E6%9D%80%E5%88%AB%E4%BA%BA%E6%88%96%E6%9D%80%E4%BD%A0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">mmap（内存映射文件）可以理解成「把磁盘文件假装成内存」：程序访问某段地址时，操作系统才把对应几页真正读进来，用不到就不占内存，内存紧张时还能把干净页直接丢掉、下次再从盘上取回。对几个 GB 的只读权重来说，这等于操作系统白送了一套按需加载与回收机制——自己做，做不出更便宜的了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写压缩换入换出：解压的 CPU 与能耗代价把它挤出了热路径。iOS 扩展进程的限额差异只提示到「更严」为止，具体数值随系统版本变。多进程共享只读页省的是物理内存，记账要按共享口径。进程保活的对抗手段不写：那是在和操作系统抢资源，赢不了也不该赢。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内存账四项：权重、KV、激活缓冲、运行时；按峰值口径，KV 按上下文上限预提。</li><li>mmap 是地基：缺页、回收与第一层换入换出由内核免费提供。</li><li>压力响应按固定顺序让路：丢缓存与 KV、卸大模型、降档小模型。</li><li>常驻与按需分档加显式预热，把切换成本变成受控的工程量。</li><li>出处：Apple Jetsam 与 Android lowmemorykiller、onTrimMemory 机制文档；GGUF 容器设计说明；按本课程口径整理。</li></ul>',5))])}const k=m(d,[["render",p]]);export{g as __pageData,k as default};
